"use client";

/**
 * Daily Brief card (Wave 12, A3).
 *
 * Shows the morning brief generated by the Worker (`GET /brief`, `POST /brief/generate`), combining weather, calendar,
 * tasks, pending approvals, provider key health, research digest, and an optional AI summary. Includes a "Read aloud"
 * button powered by `window.speechSynthesis`.
 */
import { useCallback, useEffect, useRef, useState } from "react";
import { Badge, Panel } from "@/components/kit";
import { relative } from "@/lib/time";
import {
  fetchDailyBrief,
  generateDailyBriefNow,
  isWorkerConfigured,
  WorkerApiError,
  type DailyBriefRecord,
} from "@/lib/workerApi";

export default function BriefCard({ token, onUnauthorized }: { token: string; onUnauthorized: () => void }) {
  const [brief, setBrief] = useState<DailyBriefRecord | null>(null);
  const [busy, setBusy] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const alive = useRef(true);

  const load = useCallback(async () => {
    if (!isWorkerConfigured()) return;
    try {
      const out = await fetchDailyBrief(token);
      if (alive.current) {
        setBrief(out.brief);
        setError(null);
      }
    } catch (err) {
      if (err instanceof WorkerApiError && err.status === 401) onUnauthorized();
      else if (alive.current) setError(err instanceof Error ? err.message : "Could not load the daily brief.");
    }
  }, [token, onUnauthorized]);

  useEffect(() => {
    alive.current = true;
    void load();
    return () => {
      alive.current = false;
      if (typeof window !== "undefined" && "speechSynthesis" in window) {
        window.speechSynthesis.cancel();
      }
    };
  }, [load]);

  async function handleGenerate(send: boolean) {
    setBusy(true);
    setError(null);
    try {
      const out = await generateDailyBriefNow(token, send);
      if (alive.current) setBrief(out.brief);
    } catch (err) {
      if (err instanceof WorkerApiError && err.status === 401) onUnauthorized();
      else if (alive.current) setError(err instanceof Error ? err.message : "Could not generate the daily brief.");
    } finally {
      if (alive.current) setBusy(false);
    }
  }

  function toggleReadAloud() {
    if (typeof window === "undefined" || !("speechSynthesis" in window) || !brief) return;
    if (speaking) {
      window.speechSynthesis.cancel();
      setSpeaking(false);
      return;
    }
    const utterance = new SpeechSynthesisUtterance(brief.aiSummary ? `${brief.aiSummary}. ${brief.text}` : brief.text);
    utterance.onend = () => setSpeaking(false);
    utterance.onerror = () => setSpeaking(false);
    setSpeaking(true);
    window.speechSynthesis.speak(utterance);
  }

  if (!isWorkerConfigured()) return null;

  return (
    <Panel
      title="Daily Brief"
      eyebrow={brief ? `Morning brief for ${brief.date}` : "Morning summary"}
      tone="ion"
      actions={
        <>
          {brief ? (
            <button className="btn btn-quiet" onClick={toggleReadAloud}>
              {speaking ? "Stop reading" : "Read aloud"}
            </button>
          ) : null}
          <button className="btn" disabled={busy} onClick={() => void handleGenerate(false)}>
            {busy ? "Generating…" : "Generate now"}
          </button>
          <button className="btn btn-primary" disabled={busy} onClick={() => void handleGenerate(true)}>
            Send to channels
          </button>
        </>
      }
    >
      {error ? (
        <p className="field-error" role="alert">
          {error}
        </p>
      ) : null}
      {!brief ? (
        <p className="e-dim">
          No daily brief has been generated yet. The built-in schedule runs at 07:30 America/Chicago once a notification
          channel is connected, or you can choose <strong>Generate now</strong>.
        </p>
      ) : (
        <div data-testid="daily-brief-card">
          {brief.aiSummary ? <p className="e-hint">{brief.aiSummary}</p> : null}
          <div className="chip-row" style={{ marginBottom: 8 }}>
            <Badge tone={brief.healthOk ? "ok" : "warn"}>{brief.healthOk ? "Health green" : "Health needs check"}</Badge>
            <Badge tone="neutral">{brief.tasks.done} done (24h)</Badge>
            {brief.pendingApprovals > 0 ? <Badge tone="corona">{brief.pendingApprovals} approval waiting</Badge> : null}
            <span className="e-dim e-num">Updated {relative(brief.generatedAt)}</span>
          </div>
          <pre className="result-box" tabIndex={0} style={{ whiteSpace: "pre-wrap" }}>
            {brief.text}
          </pre>
        </div>
      )}
    </Panel>
  );
}
